<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sorting Algorithm Visualizer</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: #1a1a1a;
            color: #e0e0e0;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            padding: 20px;
        }

        .container {
            width: 100%;
            max-width: 1000px;
            background-color: #242424;
            border-radius: 12px;
            padding: 30px;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
        }

        h1 {
            text-align: center;
            margin-bottom: 30px;
            font-size: 28px;
            color: #4a9eff;
        }

        #bars {
            display: flex;
            align-items: flex-end;
            justify-content: center;
            gap: 3px;
            height: 400px;
            background-color: #1a1a1a;
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 30px;
            border: 1px solid #404040;
        }

        .bar {
            flex: 1;
            background: linear-gradient(to top, #4a9eff, #2e7fd9);
            border-radius: 4px 4px 0 0;
            transition: height 0.05s ease-out, background-color 0.05s ease-out;
            min-width: 2px;
            box-shadow: 0 2px 8px rgba(74, 158, 255, 0.3);
        }

        .bar.comparing {
            background: linear-gradient(to top, #ff6b6b, #d63031);
            box-shadow: 0 2px 8px rgba(255, 107, 107, 0.5);
        }

        .bar.sorted {
            background: linear-gradient(to top, #51cf66, #2f9e44);
            box-shadow: 0 2px 8px rgba(81, 207, 102, 0.3);
        }

        .controls {
            display: flex;
            gap: 15px;
            justify-content: center;
            flex-wrap: wrap;
        }

        button {
            padding: 12px 28px;
            font-size: 16px;
            font-weight: 600;
            border: none;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.3s ease;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        #sort {
            background-color: #4a9eff;
            color: #fff;
        }

        #sort:hover:not(:disabled) {
            background-color: #357abd;
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(74, 158, 255, 0.4);
        }

        #shuffle {
            background-color: #ffa500;
            color: #fff;
        }

        #shuffle:hover:not(:disabled) {
            background-color: #cc8400;
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(255, 165, 0, 0.4);
        }

        #reset {
            background-color: #888;
            color: #fff;
        }

        #reset:hover:not(:disabled) {
            background-color: #666;
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(136, 136, 136, 0.4);
        }

        button:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .info {
            text-align: center;
            margin-top: 20px;
            font-size: 14px;
            color: #888;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Sorting Visualizer</h1>
        <div id="bars"></div>
        <div class="controls">
            <button id="shuffle">Shuffle</button>
            <button id="sort">Sort</button>
            <button id="reset">Reset</button>
        </div>
        <div class="info">
            <p>Click "Shuffle" to randomize, then "Sort" to animate the sorting process.</p>
        </div>
    </div>

    <script>
        const ARRAY_SIZE = 50;
        const ANIMATION_SPEED = 10;

        class SortVisualizer {
            constructor() {
                this.array = [];
                this.originalArray = [];
                this.sortIndex = 0;
                this.compareIndices = [];
                this.isSorting = false;
                this.bubbleSortState = { i: 0, j: 0 };
                this.init();
            }

            init() {
                this.generateArray();
                this.render();
            }

            generateArray() {
                this.array = Array.from({ length: ARRAY_SIZE }, (_, i) => i + 1);
                this.originalArray = [...this.array];
                this.bubbleSortState = { i: 0, j: 0 };
                this.compareIndices = [];
            }

            shuffle() {
                for (let i = this.array.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [this.array[i], this.array[j]] = [this.array[j], this.array[i]];
                }
                this.bubbleSortState = { i: 0, j: 0 };
                this.compareIndices = [];
                this.render();
            }

            render() {
                const barsContainer = document.getElementById('bars');
                barsContainer.innerHTML = '';
                const maxValue = Math.max(...this.array);

                this.array.forEach((value, index) => {
                    const bar = document.createElement('div');
                    bar.className = 'bar';
                    const heightPercent = (value / maxValue) * 100;
                    bar.style.height = `${heightPercent}%`;

                    if (this.compareIndices.includes(index)) {
                        bar.classList.add('comparing');
                    } else if (this.isSorted(index)) {
                        bar.classList.add('sorted');
                    }

                    barsContainer.appendChild(bar);
                });
            }

            isSorted(index) {
                return index > this.bubbleSortState.i;
            }

            sortStep() {
                if (this.sorted()) {
                    this.isSorting = false;
                    this.compareIndices = [];
                    this.render();
                    return true;
                }

                const { i, j } = this.bubbleSortState;
                const n = this.array.length;

                if (i >= n - 1) {
                    this.isSorting = false;
                    this.compareIndices = [];
                    this.render();
                    return true;
                }

                if (j >= n - 1 - i) {
                    this.bubbleSortState.i++;
                    this.bubbleSortState.j = 0;
                    this.compareIndices = [];
                    this.render();
                    return false;
                }

                this.compareIndices = [j, j + 1];

                if (this.array[j] > this.array[j + 1]) {
                    [this.array[j], this.array[j + 1]] = [this.array[j + 1], this.array[j]];
                }

                this.bubbleSortState.j++;
                this.render();
                return false;
            }

            sorted() {
                for (let i = 0; i < this.array.length - 1; i++) {
                    if (this.array[i] > this.array[i + 1]) {
                        return false;
                    }
                }
                return true;
            }

            getArray() {
                return [...this.array];
            }

            setArray(arr) {
                this.array = [...arr];
                this.originalArray = [...arr];
                this.bubbleSortState = { i: 0, j: 0 };
                this.compareIndices = [];
                this.isSorting = false;
                this.render();
            }
        }

        const visualizer = new SortVisualizer();

        // Expose API on window
        window.viz = {
            array() {
                return visualizer.getArray();
            },
            setArray(a) {
                visualizer.setArray(a);
            },
            sortStep() {
                return visualizer.sortStep();
            },
            sorted() {
                return visualizer.sorted();
            }
        };

        // UI Event Listeners
        document.getElementById('shuffle').addEventListener('click', () => {
            if (!visualizer.isSorting) {
                visualizer.shuffle();
            }
        });

        document.getElementById('sort').addEventListener('click', () => {
            if (visualizer.isSorting || visualizer.sorted()) return;

            visualizer.isSorting = true;
            const sortInterval = setInterval(() => {
                if (visualizer.sortStep()) {
                    clearInterval(sortInterval);
                    visualizer.isSorting = false;
                }
            }, ANIMATION_SPEED);
        });

        document.getElementById('reset').addEventListener('click', () => {
            if (!visualizer.isSorting) {
                visualizer.init();
            }
        });
    </script>
</body>
</html>
